argv:
$ErrorActionPreference='Stop'
$c=@(Get-NetTCPConnection -LocalPort 17449 -State Listen -ErrorAction SilentlyContinue)
Write-Output ('LISTENER_COUNT='+$c.Count)
foreach($e in $c){
 Write-Output ('PORT_OWNER_PID='+$e.OwningProcess)
 $proc=Get-Process -Id $e.OwningProcess -ErrorAction SilentlyContinue
 Write-Output ('PORT_OWNER_PROCESS='+[string]$proc.ProcessName)
}
try {
 $x=Invoke-RestMethod -Uri 'http://127.0.0.1:17449/api/live' -TimeoutSec 5
 Write-Output ('ENDPOINT_CONTRACT='+[string]$x.contract)
 Write-Output ('ENDPOINT_READONLY='+[string]$x.readOnly)
 Write-Output ('ENDPOINT_OPEN_COUNT='+[string]$x.openCount)
 Write-Output ('ENDPOINT_NO_SEND='+[string]$x.guardrails.noSend)
} catch {
 Write-Output ('ENDPOINT_NOT_VERIFIED='+[string]$_.Exception.GetType().Name)
}
Write-Output ('CHECK_ANOTHER_PORT_17450='+[bool](Get-NetTCPConnection -LocalPort 17450 -State Listen -ErrorAction SilentlyContinue))
